import json,pathlib
P=pathlib.Path('research/asia');r=json.load(open(P/'reviews.json'))
def add(id,diff,reason,sol='',statement=None,topic=None,subtopics=None,**kw):
 r[id]={'difficulty':diff,'reason':reason,'proofConfidence':'checked' if diff is not None else 'unresolved',**kw}
 if sol:r[id]['solutionOverride']=sol
 if statement:r[id]['statementOverride']=statement
 if topic:r[id]['topic']=topic
 if subtopics:r[id]['subtopics']=subtopics;r[id]['tags']=subtopics
# Japanese Mathematical Olympiad 2024, first round: all twelve questions.
add('jpn_2024_d9ab95',1,'Factoring the two factorial differences cancels their common factorial immediately.')
add('jpn_2024_70520f',2,'Checking the possible prime units digits forces two cases; carrying and borrowing then determine the tens and hundreds digits.')
add('jpn_2024_f20229',3,'Two tangent-secant power equations and the given sum of lengths reduce the problem to a quadratic in BX.')
add('jpn_2024_851b05',3.5,'A five-ary majority tree needs exactly three winning children at each level; induction gives the smallest possible white certificate and then its complement.')
add('jpn_2024_eb9ad6',4,'A sharp factorwise lower bound for the floor product forces simultaneous equality in ten inequalities, converting the problem to an lcm.',r'''For every $1\le k\le10$,
$$\left\lfloor\frac nk\right\rfloor\ge\frac{n-k+1}{k},$$
with equality precisely when $n\equiv-1\pmod k$. Multiplying gives the required inequality against $\binom n{10}$. As all factors are positive, equality of products requires equality in every factor. Thus $n+1$ is divisible by each of $1,\ldots,10$. Their least common multiple is $2520$, so the smallest allowed value is $\boxed{2519}$.''',statement=r'''Find the least integer $n\ge10$ for which $\prod_{k=1}^{10}\lfloor n/k\rfloor=\binom n{10}$.''',topic='Number Theory',subtopics=['Floors & fractional parts','Divisibility & GCD','Factorials & binomial coefficients'])
add('jpn_2024_c08f01',5.5,'Tangency must first produce a cyclic quadrilateral and two different triangle similarities; a final secant-power equation determines the scale.',r'''The tangent-chord angle relations show that $A,B,F,C$ are concyclic and that triangles $DEB$ and $AEC$ are similar. Consequently $EB/EC=BD/AC=2/5$. Write $EB=2t$, $EC=5t$. Cyclicity also gives $EBA\sim EFC$, whence $EF=4t$ and $EA=5t/2$ because $AB=5$ and $CF=10$. The power of $A$ relative to the circle tangent at $B$ now gives
$$25=AB^2=AE\cdot AF=\frac{5t}{2}\left(\frac{5t}{2}+4t\right)=\frac{65t^2}{4}.$$
Thus $t=2\sqrt{65}/13$ and $\boxed{BC=14\sqrt{65}/13}$.''',statement=r'''In an isosceles triangle $ABC$, $AB=AC=5$. Take $D\in AB$ with $AD=3$ and $E\in BC$. A circle through $E$ touches $AB$ at $B$ and is tangent to the circumcircle of $ADE$; it meets the line $AE$ again at $F$. If $CF=10$, determine $BC$.''',topic='Geometry',subtopics=['Circles & tangency','Similarity & congruence','Power of a point & radical axes'])
add('jpn_2024_a26186',5.5,'The square root is restricted to two residues modulo a prime fourth power; range bounds reduce the question to two explicit prime families.',r'''Put $u=p^3+p^2+1$. Direct expansion gives
$$u^2=p^4(p+1)^2+2p^3+2p^2+1.$$
If the square in the question is $v^2$, then $v^2\equiv u^2\pmod{p^4}$. Because $p\nmid u$ and $p$ is odd, the factors $v-u,v+u$ cannot both be divisible by $p$; hence $v\equiv\pm u\pmod{p^4}$. The bound $a<p^4$ gives $0<v<p^4$, so $v=u$ or $v=p^4-u$. These yield respectively
$$a=(p+1)^2\quad\text{or}\quad a=(p^2-p-1)^2-2.$$
The first family with $a\le2024$ uses the thirteen primes $3\le p\le43$. The second uses $p=3,5,7$, giving $23,359,1679$. These three values are not squares, so there is no overlap. All sixteen satisfy $a<p^4$. The answer is $\boxed{16}$.''',statement=r'''How many integers $a$ with $1\le a\le2024$ admit an odd prime $p$ such that $a<p^4$ and $ap^4+2p^3+2p^2+1$ is a square?''',topic='Number Theory',subtopics=['Modular arithmetic','Primes','Squares & powers'])
add('jpn_2024_714449',4.5,'Special substitutions force constant absolute value, but the remaining independent signs and the exclusion of odd squares must both be identified.',r'''Write the equation as $P(m,n)$. From $P(0,0)$, $f(0)=0$ or $2$. In the first case $P(m,0)$ forces $f\equiv0$.

In the second, $P(0,1)$ gives $f(1)=-1$ or $2$; the former makes $P(1,1)$ impossible. Comparing $P(m,0)$ and $P(m,1)$ gives $f(m+1)^2=f(m)^2$, so every value is $\pm2$. The same substitutions imply $f(2m)=2$, and $P(0,n)$ gives $f(n^2)=2$. Conversely any assignment of signs at the odd nonsquares, with value $2$ everywhere else, satisfies the equation: its right side is always $2+2$. There are $1012$ odd positive integers at most $2024$, of which $22$ are squares. The requested count is therefore $\boxed{1+2^{990}}$.''',statement=r'''Let $f:\mathbb Z_{\ge0}\to\mathbb Z$ satisfy $f(m+n)^2=f(m|f(n)|)+f(n^2)$ for every pair of nonnegative integers $m,n$. How many different tuples $(f(0),\ldots,f(2024))$ can occur?''',topic='Algebra',subtopics=['Functional equations','Equations & systems'])
add('jpn_2024_957af4',5,'Two similarities connect an angle-bisector configuration to a new cyclic quadrilateral, after which a short power calculation gives the length.',r'''The angle condition and the bisector at $D$ give $DAE\sim DFC$, and hence $DAF\sim DEC$. Put $G=AF\cap BC$. The resulting angle relations imply $BG=BA=7$ and $D,F,G,C$ concyclic. Since $BE=5$, we have $EG=2$ and $EC=13$. Power from $E$ in the latter circle gives $EF\cdot ED=EG\cdot EC=26$. Thus $ED=26/3$ and $\boxed{DF=ED-EF=17/3}$.''',statement=r'''Let $ABCD$ be cyclic with $AB=7$ and $BC=18$. The bisector of $\angle ADC$ meets $BC$ at $E$. Choose $F$ on $DE$ so that $\angle AED=\angle FCD$. Given $BE=5$ and $EF=3$, find $DF$.''',topic='Geometry',subtopics=['Angles & cyclic quadrilaterals','Similarity & congruence','Power of a point & radical axes'])
add('jpn_2024_8d022e',6.5,'Local restrictions force every change boundary to extend across the whole board; the quotient grid then collapses to a sequence along its diagonals.',r'''Call an edge separating different letters a boundary. Inspection of an allowed $2\times2$ block shows that its top edge is a boundary exactly when its bottom edge is; likewise for left and right. Thus boundaries form complete horizontal or vertical grid lines. If their numbers are $s,t$, the number of unlike adjacent pairs is $100(s+t)$, so $s+t=100$.

The selected lines split the board into constant rectangles. Across each selected line the letters differ. At a crossing, the upper-right and lower-left rectangles have the same letter: this holds both in the two-letter alternating case and by the stated three-letter rule. Consequently the rectangle in position $(i,j)$ has letter $a_{i+j-1}$ for a sequence $a_1,\ldots,a_{101}$ with adjacent terms unequal. Conversely every such sequence and every choice of $100$ of the $198$ internal grid lines gives an allowed board. The choices are recoverable from the board, so the answer is $\boxed{\binom{198}{100}\,3\,2^{100}}$.''',statement=r'''Fill a $100\times100$ board with J, M and O. Each $2\times2$ block must either be constant, have two of each of two letters, or use all three letters with equal upper-right and lower-left entries. Count the fillings having exactly $10000$ adjacent pairs of different letters. Rotations and reflections count separately.''',topic='Combinatorics',subtopics=['Colouring','Counting','Combinatorial geometry','Bijections'])
add('jpn_2024_5a6712',6.5,'The triangle condition becomes a bound on the global range of f(x)-x; a balanced lower-bound sum must be matched by a piecewise extremal function.',r'''Put $h(x)=f(x)-x$. The triangle conditions are equivalent to $h(b)-h(a)<f(c)+c$ for every $a,b,c$. Taking $a=c=1$ and then $b=c=1$ bounds the integer-valued function $h$, so let its minimum and maximum be $m,M$, and put $r=M-m$. Since $h(34)=1990$, we have $M\ge1990$, hence
$$f(x)\ge r-x+1,\qquad f(x)\ge1990+x-r.$$
Use the first bound for $100\le x\le149$ and the second for $150\le x\le199$. Their sum is $50\cdot1990+2550=102050$.

For equality define $f(x)=1145-x$ on $100\le x\le149$, $f(x)=846+x$ on $150\le x\le199$, and $f(x)=1990+x$ otherwise. This has $846\le h(x)\le1990$ and $f(x)+x\ge1145>1990-846$, so all triangle inequalities hold. It also has $f(34)=2024$ and the required sum $\boxed{102050}$.''',statement=r'''A function $f:\mathbb Z_{>0}\to\mathbb Z_{>0}$ has $f(34)=2024$. For every positive integer triple $a,b,c$, the numbers $a+f(b)$, $b+f(c)$ and $c+f(a)$ are sides of a nondegenerate triangle. Determine the least possible value of $\sum_{x=100}^{199}f(x)$.''',topic='Algebra',subtopics=['Functional equations','Inequalities','Functions & graphs'])
add('jpn_2024_2726dd',9.5,'Counting the image of the unitary-residue convolution requires squarefree period reduction and a tensor decomposition, with separate prime-power divisibility multiplicities.')
# Final round, all five questions.
add('jpn_2024_e48072',4,'Permutation preserves the sum of squares; expanding exposes a sum of squared consecutive differences, after which the common value must vanish.',r'''Because the two lists are permutations, $\sum_i(a_i-2a_{i+1})^2=\sum_i a_i^2$, where indices are cyclic. Expanding and cancelling gives
$$0=4\sum_i a_i^2-4\sum_i a_i a_{i+1}=2\sum_i(a_i-a_{i+1})^2.$$
All $a_i$ therefore have a common value $c$. The two constant lists are $(c,\ldots,c)$ and $(-c,\ldots,-c)$, so $c=0$.''',statement=r'''For a cyclic list of real numbers $a_1,\ldots,a_n$, suppose that $a_1-2a_2,a_2-2a_3,\ldots,a_n-2a_1$ is a permutation of the original list. Prove that all entries are zero.''',topic='Algebra',subtopics=['Algebraic identities','Equations & systems'])
add('jpn_2024_9efea6',5.5,'An lcm substitution with a carefully chosen coprime residue proves divisibility of every value; an iterated value then lies between consecutive multiples.',r'''Fix $m$ and choose $n$ so that $f(m)+n\equiv1\pmod m$. The identity implies $m\mid\operatorname{lcm}(f(m),f(m)+n)$, and the second lcm argument is coprime to $m$. Comparing prime exponents yields $m\mid f(m)$. In particular $f(m)\ge m$.

Now substitute $n=f(m)$. The right side is $2f(m)$, while the left side is divisible by $f(m+f(f(m)))$, hence by $m+f(f(m))$. Because $f(f(m))\ge f(m)$, this divisor is larger than $f(m)$ and cannot exceed $2f(m)$; it must equal $2f(m)$. But $f(f(m))$ is a multiple of $f(m)$, lying in $[f(m),2f(m))$, so it equals $f(m)$. The displayed equality now gives $m=f(m)$. Conversely $f(m)=m$ satisfies the identity. Thus the identity function is the only answer.''',statement=r'''Determine all functions $f:\mathbb Z_{>0}\to\mathbb Z_{>0}$ satisfying $\operatorname{lcm}(m,f(m+f(n)))=\operatorname{lcm}(f(m),f(m)+n)$ for all positive integers $m,n$.''',topic='Algebra',subtopics=['Functional equations'],tags=['Functional equations','Divisibility & GCD'])
add('jpn_2024_5e3413',8,'The boundary-point obstruction is short, but attaining it requires two interlocking families of sloping polylines and checking five distinct coverage regions.')
add('jpn_2024_b8af00',8.5,'The configuration needs a hidden arc midpoint, a reflected rhombus, and a chain of circle-centre identifications before the required tangent is visible.')
add('jpn_2024_48b428',9,'A parity descent first excludes repeated variables and equal pair products, then requires a three-term valuation lemma and a separate smallest-exponent obstruction.')
# Korean national final 2023: all four available records; Q3 and Q4 remain missing.
add('kor_2023_7a2a3c',4.5,'Two equal-distance conditions linearize the circle equations; their sum identifies the projection of P onto every secant through A.',r'''Take $A$ as the origin. Write the two circumcircles as $|v|^2=u\cdot v$ and $|v|^2=w\cdot v$. Along the ray $AB$, write $B=b e$ and $D=d e$, with $e$ a unit vector. The equations give $u\cdot e=b$ and $w\cdot e=d$. Since $PB=PD$, $2P\cdot e=b+d$. The same reasoning on the nonparallel ray $AC$ gives the corresponding equality there, so $2P=u+w$.

On the line $AX$, choose a unit direction $t$. The two other circle intersections have signed coordinates $u\cdot t$ and $w\cdot t$. Their midpoint is therefore $((u+w)\cdot t)t/2=(P\cdot t)t$, the orthogonal projection of $P$ onto $AX$. Thus $P$ lies on the perpendicular bisector of $XY$, proving $PX=PY$. The same equations also cover tangent or coincident limiting intersections.''',statement=r'''In an acute triangle $ABC$ with $AB<AC$, take interior points $D\in AB$ and $E\in AC$. Suppose $PB=PD$ and $PC=PE$. A point $X$ lies on the open arc $AC$ of the circumcircle of $ABC$ avoiding $B$. The line $AX$ meets the circumcircle of $ADE$ again at $Y$. Show that $PX=PY$.''',topic='Geometry',subtopics=['Coordinates & vectors','Circles & tangency'])
add('kor_2023_5952ef',6.5,'Finite nonempty neighbourhoods give a reciprocal incidence graph; splitting an interval into two sets produces incompatible finiteness conclusions.',r'''For $x>0$ let $A_x=\{y>0:(x+f(y))(y+f(x))\le4\}$. These sets are nonempty and finite; membership is symmetric. If $x<y$ and $f(x)\le f(y)$, positivity gives $A_y\subseteq A_x$.

For fixed $b$, the set $L_b=\{s<b:f(s)\le f(b)\}$ is finite. Indeed, choose $z\in A_b$; for every $s\in L_b$, inclusion gives $z\in A_s$, hence $s\in A_z$.

Suppose $a<b$ and $f(a)\le f(b)$. For $a<s<b$, either $f(s)\le f(b)$, putting $s$ in the finite set $L_b$, or $f(s)>f(b)\ge f(a)$, giving $A_s\subseteq A_a$. In the latter case choose $t\in A_s$; symmetry gives $s\in A_t$. Thus the whole interval $(a,b)$ lies in the finite set $L_b\cup\bigcup_{t\in A_a}A_t$, a contradiction. Therefore $f(a)>f(b)$ whenever $a<b$.''',statement=r'''Let $f:(0,\infty)\to(0,\infty)$. Assume that for each $x>0$, the set of positive $y$ satisfying $(x+f(y))(y+f(x))\le4$ is nonempty and finite. Prove that $f$ is strictly decreasing.''',topic='Algebra',subtopics=['Functional equations','Functions & graphs'],note='The transcription said y was real although f is defined only on positive reals; the quantifier is corrected to positive y. The proof also repairs an equality case in the finite-set argument.')
add('kor_2023_878c28',7,'Passing to adjacent differences makes an interval move a directed transfer; residue-class induction supplies the upper bound, while connected components prove a matching obstruction.',r'''Put $x_0=x_{n+1}=0$ and $y_i=x_i-x_{i+1}$ for $0\le i\le n$. A move subtracts $1$ from some $y_i$ and adds $1$ to a later $y_j$. We must make every $y_i$ divisible by $3$, and their residues sum to zero.

For a list of $L=n+1$ residues the upper bound is $\lceil2L/3\rceil$. Delete zero residues. If a $1$ precedes a $2$, one transfer clears both. Three $1$'s can be cleared in two transfers to the last of them; three $2$'s in two transfers from the first. Induction applies after these deletions. If none applies, the only nonempty residual lists are $(2,1)$, needing two transfers, or $(2,2,1,1)$, cleared by the transfers $(1,2),(1,4),(3,4)$. In each case the bound holds; deletion of a pair costs one and deletion of a triple costs two, so the induction preserves it.

For the lower bound choose the residues to be all $2$ when $L\equiv0\pmod3$, all $2$ followed by one $1$ when $L\equiv2$, and all $2$ followed by two $1$'s when $L\equiv1$. Regard transfers as directed edges on the $L$ positions. In each connected component, the initial residue sum must be zero. If it has $k$ vertices and no $1$, then $3\mid k$ and at least $k-1\ge2k/3$ edges are needed. With one $1$, $k\equiv2\pmod3$; with two, $k\equiv1\pmod3$. The connectedness bound is at least $\lceil2k/3\rceil$ in these cases except possibly $k=2$. That exception consists of a $2$ preceding a $1$, and its only directed edge must be used at least twice. Thus every component needs at least $\lceil2k/3\rceil$ moves, giving at least $\lceil2L/3\rceil$ overall. Every chosen residue list arises from positive initial box counts by taking suitable representatives. Hence the maximum is $\boxed{\lceil(2n+2)/3\rceil}$.''',statement=r'''There are $n$ boxes initially containing positive numbers $x_1,\ldots,x_n$ of balls. One move adds a ball to every box in a nonempty consecutive interval. Let $f(x_1,\ldots,x_n)$ be the fewest moves that make all box counts divisible by $3$. Determine the maximum of $f$ over all positive initial counts.''',topic='Combinatorics',subtopics=['Invariants','Modular arithmetic','Graph theory','Algorithms & constructions'],note='Supplied a connected-component proof of the sharp lower bound, which was only asserted in the downloaded solution.')
add('kor_2023_57d25e',6,'Introduces cyclic correlations with zero average; a Lipschitz bound between shifts is summed over shortest cyclic distances and then applied three times.',r'''Let $E=\sum_i((a_i-a_{i+1})^2+(b_i-b_{i+1})^2)$ and $S_j=\sum_i a_{i+j}(b_i-b_{i+1})$, with all indices modulo $n$. The inequality $2|uv|\le u^2+v^2$ gives $|S_j-S_{j+1}|\le E/2$. Also $\sum_{j=0}^{n-1}S_j=0$. Consequently
$$nS_0=\sum_{j=0}^{n-1}(S_0-S_j)\le\frac E2\sum_{j=0}^{n-1}\min(j,n-j)\le\frac{n^2E}{8}.$$
Thus $\sum_i a_i(b_i-b_{i+1})\le nE/8$. Apply this inequality with the $b$-sequence shifted by $0,1,2$ and add. The three left sides telescope to $\sum_i a_i(b_i-b_{i+3})$, while the difference energy is unchanged by shifts. This proves the desired bound $3nE/8$.''',statement=r'''For $n\ge3$ and real cyclic sequences $a_i,b_i$ (indices interpreted modulo $n$), prove $\sum_{i=1}^n a_i(b_i-b_{i+3})\le\frac{3n}{8}\sum_{i=1}^n((a_i-a_{i+1})^2+(b_i-b_{i+1})^2)$.''',topic='Algebra',subtopics=['Inequalities','Sequences & recurrences'])
(P/'reviews.json').write_text(json.dumps(r,ensure_ascii=False,indent=2));print('reviews',len(r))
